QPushButton* action(QGridLayout* grid,int row,int column,const QString& text,const QString& id){auto* b=new QPushButton(text);b->setObjectName(id);grid->addWidget(b,row,column);return b;}
QLabel* caption(QVBoxLayout* layout,const QString& id){auto* text=new QLabel;text->setObjectName(id);text->setWordWrap(true);text->setTextFormat(Qt::PlainText);layout->addWidget(text);return text;}
QString assignmentName(const AssignmentData& d,bool worker,std::size_t i){const auto& dummy=worker?d.dummyWorkers:d.dummyJobs;return (worker?d.workers:d.jobs)[static_cast<int>(i)]+(std::find(dummy.begin(),dummy.end(),i)!=dummy.end()?QStringLiteral(" (dummy)"):QString());}
QString number(const AssignmentController& c,double x){return QString::fromStdString(core::NumberFormatter(c.data()->format).format(x));}
QStringList assignmentLines(const AssignmentController& c){QStringList lines;if(!c.data() || !c.result())return lines;const auto& d=*c.data();const auto& r=*c.result();if(r.status==assignment::Status::Infeasible)return {"Infeasible: no admissible complete assignment exists."};lines<<QStringLiteral("%1 = %2").arg(d.model.sense==assignment::Sense::Minimize?QStringLiteral("Minimum cost"):QStringLiteral("Maximum profit"),number(c,r.objective));for(std::size_t i=0;i<r.rowToColumn.size();++i){const auto j=r.rowToColumn[i];lines<<assignmentName(d,true,i)+QStringLiteral(" -> ")+(j?assignmentName(d,false,*j)+QStringLiteral("; ")+number(c,d.model.costs(i,*j)):QStringLiteral("Unassigned (dummy job)"));}return lines;}
QWidget* inputScreen(ApplicationShell& shell){auto& c=assignmentController(shell);auto* page=new QWidget;auto* layout=new QVBoxLayout(page);caption(layout,"assignment-heading")->setText("Assign workers to jobs");
    auto* fields=new QGroupBox;auto* form=new QFormLayout(fields);auto* title=new QLineEdit;title->setObjectName("assignment-title");auto* workers=new QSpinBox;workers->setObjectName("assignment-workers");auto* jobs=new QSpinBox;jobs->setObjectName("assignment-jobs");workers->setRange(1,100);jobs->setRange(1,100);workers->setValue(3);jobs->setValue(3);form->addRow("Title:",title);form->addRow("Workers:",workers);form->addRow("Jobs:",jobs);auto* sense=new QComboBox;sense->addItems({"Minimize cost","Maximize profit"});sense->setObjectName("assignment-sense");form->addRow("Objective:",sense);layout->addWidget(fields);
    auto* controls=new QGridLayout;auto* init=action(controls,0,0,"Initialize","assignment-initialize");auto* example=action(controls,0,1,"Load example","assignment-example");auto* open=action(controls,1,0,"Open","assignment-open");auto* save=action(controls,1,1,"Save As","assignment-save");layout->addLayout(controls);
    auto* view=new QTableView;view->setObjectName("assignment-grid");view->setModel(c.grid());view->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);view->verticalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);view->setAlternatingRowColors(true);view->setEditTriggers(QAbstractItemView::DoubleClicked|QAbstractItemView::EditKeyPressed|QAbstractItemView::AnyKeyPressed);layout->addWidget(view,1);
    auto* help=caption(layout,"assignment-help");help->setText("Enter X for a forbidden pair; a number permits it again. Double-click a cost to edit, or a heading to rename. Rectangular models leave extra workers unassigned or jobs unused.");
    auto* output=new QGroupBox("Number format");auto* fmt=new QHBoxLayout(output);auto* notation=new QComboBox;notation->addItems({"Decimal","Scientific"});notation->setObjectName("assignment-notation");auto* n=new QSpinBox;auto* d=new QSpinBox;n->setRange(0,99);d->setRange(0,99);n->setObjectName("assignment-N");d->setObjectName("assignment-D");n->setValue(5);d->setValue(2);fmt->addWidget(notation);fmt->addWidget(new QLabel("N:"));fmt->addWidget(n);fmt->addWidget(new QLabel("D:"));fmt->addWidget(d);layout->addWidget(output);
    auto* footer=new QGridLayout;auto* solve=action(footer,0,0,"Solve Assignment","assignment-solve");auto* main=action(footer,0,1,"MAIN Menu","assignment-main");layout->addLayout(footer);
    const auto metadata=[&c,title,sense,n,d,notation]{if(c.data() && !c.readOnly())c.setMetadata(title->text(),sense->currentIndex()?assignment::Sense::Maximize:assignment::Sense::Minimize,{notation->currentIndex()?core::Notation::Scientific:core::Notation::Decimal,n->value(),d->value()});};
    QObject::connect(&c,&AssignmentController::commitRequested,page,[view,metadata]{if(auto* focused=QApplication::focusWidget();focused && view->isAncestorOf(focused) && focused!=view)view->setFocus();metadata();});
    const auto refresh=[&c,title,workers,jobs,sense,notation,n,d,save,solve,help]{const QSignalBlocker bt(title),bs(sense),bf(notation),bn(n),bd(d);title->setReadOnly(c.readOnly());sense->setEnabled(!c.readOnly());notation->setEnabled(!c.readOnly());n->setEnabled(!c.readOnly());d->setEnabled(!c.readOnly());save->setEnabled(bool(c.data()));solve->setEnabled(bool(c.data()));if(c.data()){const auto& data=*c.data();help->setText("Enter X for a forbidden pair; a number permits it again. Extra rows/columns use zero-cost dummies.\n"+data.mappingMessage);title->setText(data.title);sense->setCurrentIndex(data.model.sense==assignment::Sense::Maximize?1:0);notation->setCurrentIndex(data.format.notation==core::Notation::Scientific?1:0);n->setValue(data.format.n);d->setValue(data.format.d);}};
    QObject::connect(&c,&AssignmentController::changed,page,refresh);
    const auto sizes=[&c,workers,jobs]{if(c.data()){workers->setValue(static_cast<int>(c.data()->model.costs.rows()));jobs->setValue(static_cast<int>(c.data()->model.costs.columns()));}};
    QObject::connect(&c,&AssignmentController::modelReplaced,page,sizes);refresh();sizes();
    QObject::connect(title,&QLineEdit::editingFinished,page,metadata);QObject::connect(sense,&QComboBox::currentIndexChanged,page,metadata);QObject::connect(notation,&QComboBox::currentIndexChanged,page,metadata);QObject::connect(n,&QSpinBox::valueChanged,page,metadata);QObject::connect(d,&QSpinBox::valueChanged,page,metadata);
    QObject::connect(init,&QPushButton::clicked,page,[&c,title,workers,jobs]{c.initialize(title->text(),workers->value(),jobs->value());});QObject::connect(example,&QPushButton::clicked,page,[&c,sense]{c.loadExample(sense->currentIndex()==1);});QObject::connect(open,&QPushButton::clicked,page,[&c]{c.requestOpen();});QObject::connect(save,&QPushButton::clicked,page,[&c]{c.requestSave();});QObject::connect(solve,&QPushButton::clicked,page,[&c]{c.solve();});QObject::connect(main,&QPushButton::clicked,page,[&shell]{shell.navigate("main");});
    const auto rename=[&c,page](bool worker,int index){if(!c.data() || c.readOnly())return;bool ok=false;const auto& names=worker?c.data()->workers:c.data()->jobs;const auto text=QInputDialog::getText(page,"Rename",worker?"Worker name:":"Job name:",QLineEdit::Normal,names[index],&ok);if(ok)c.setName(worker,index,text);};QObject::connect(view->verticalHeader(),&QHeaderView::sectionDoubleClicked,page,[rename](int i){rename(true,i);});QObject::connect(view->horizontalHeader(),&QHeaderView::sectionDoubleClicked,page,[rename](int i){rename(false,i);});return page;}
QWidget* resultScreen(ApplicationShell& shell){auto& c=assignmentController(shell);auto* page=new QWidget;auto* layout=new QVBoxLayout(page);auto* title=caption(layout,"assignment-result-title");auto* status=caption(layout,"assignment-objective");auto* tabs=new QTabWidget;auto* pairs=new QTableWidget(0,3);pairs->setObjectName("assignment-pairs");pairs->setHorizontalHeaderLabels({"Worker","Job","Cost / profit"});pairs->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);pairs->horizontalHeader()->setStretchLastSection(true);pairs->setEditTriggers(QAbstractItemView::NoEditTriggers);auto* certificate=new QTableWidget(0,3);certificate->setObjectName("assignment-certificate");certificate->setHorizontalHeaderLabels({"Entry","Index","Potential"});certificate->horizontalHeader()->setSectionResizeMode(QHeaderView::ResizeToContents);certificate->horizontalHeader()->setStretchLastSection(true);certificate->setEditTriggers(QAbstractItemView::NoEditTriggers);tabs->addTab(pairs,"Assignment");tabs->addTab(certificate,"Dual certificate");auto* steps=new HistoryView("assignment");steps->setObjectName("assignment-history");tabs->addTab(steps,"Steps / Iterations");layout->addWidget(tabs,1);caption(layout,"assignment-certificate-help")->setText("Certificate uses square zero-padding and negated profits for maximization. Dummy pairs are not real assignments.");auto* footer=new QGridLayout;auto* input=action(footer,0,0,"View/Modify input","assignment-result-input");auto* print=action(footer,0,1,"Write to Printer","assignment-print");auto* main=action(footer,1,0,"MAIN Menu","assignment-result-main");auto* save=action(footer,1,1,"Save As","assignment-result-save");layout->addLayout(footer);
    const auto refresh=[&c,title,status,pairs,certificate,steps,print,save]{pairs->setRowCount(0);certificate->setRowCount(0);steps->setHistory({},{});print->setEnabled(bool(c.result()));save->setEnabled(bool(c.data()));title->setText(c.data()?c.data()->title:QString());status->setText(c.result()?assignmentLines(c).front():QStringLiteral("No current solution. Solve the model first."));if(!c.data() || !c.result())return;const auto& data=*c.data();const auto& r=*c.result();QStringList titles;for(std::size_t i=0;i<r.history.size();++i)titles<<QString::number(i+1)+". "+QString::fromStdString(r.history[i].event);steps->setHistory(titles,[&c](int i){return assignmentStepText(*c.data(),*c.result(),i);});if(r.status==assignment::Status::Infeasible)return;pairs->setRowCount(static_cast<int>(r.rowToColumn.size()));for(std::size_t i=0;i<r.rowToColumn.size();++i){const auto j=r.rowToColumn[i];const QStringList row{assignmentName(data,true,i),j?assignmentName(data,false,*j):QStringLiteral("Unassigned"),j?number(c,data.model.costs(i,*j)):QStringLiteral("Not applicable")};for(int col=0;col<3;++col)pairs->setItem(static_cast<int>(i),col,new QTableWidgetItem(row[col]));}certificate->setRowCount(static_cast<int>(r.rowPotential.size()+r.columnPotential.size()));int row=0;for(const bool worker:{true,false}){const auto& potentials=worker?r.rowPotential:r.columnPotential;for(std::size_t i=0;i<potentials.size();++i){certificate->setItem(row,0,new QTableWidgetItem(worker?"Row":"Column"));certificate->setItem(row,1,new QTableWidgetItem(QString::number(i+1)));certificate->setItem(row++,2,new QTableWidgetItem(number(c,potentials[i])));}}};QObject::connect(&c,&AssignmentController::resultChanged,page,refresh);QObject::connect(&c,&AssignmentController::changed,page,refresh);refresh();
    QObject::connect(input,&QPushButton::clicked,page,[&shell]{shell.navigate("assignment/input");});QObject::connect(main,&QPushButton::clicked,page,[&shell]{shell.navigate("main");});QObject::connect(save,&QPushButton::clicked,page,[&c]{c.requestSave();});QObject::connect(print,&QPushButton::clicked,page,[&shell,&c]{if(requestLpPrint(&shell,[&c,&shell](QPrinter& printer){return printAssignment(printer,c,shell.font());})==PrintOutcome::Failed)c.fail("Could not complete printing");});return page;}
void fileMenu(ApplicationShell& shell,QMenuBar& bar){auto& c=assignmentController(shell);auto* file=bar.addMenu("File");file->addAction("Open",&c,[&c]{c.requestOpen();});file->addAction("Save As",&c,[&c]{c.requestSave();});auto* imports=file->addMenu("Import unit Transportation");for(bool profit:{false,true})imports->addAction(profit?"Negated profits (maximize)":"Costs (minimize)",&shell,[&c,profit]{const auto p=c.dialogs().chooseOpen();if(p)c.importTransportation(p->path,profit);});}
