ModuleDescriptor assignmentModule(){ModuleDescriptor module{"assignment","Assignment Problems","assignment/input",{}, {}};module.beforeLeave=[](ApplicationShell& shell,const QString& from,const QString& to){return !from.startsWith("assignment/") || to.startsWith("assignment/") || assignmentController(shell).allowLeave();};module.screens.append({"assignment/input","ASSIGNMENT PROBLEMS",inputScreen,fileMenu});module.screens.append({"assignment/result","ASSIGNMENT PROBLEMS",resultScreen,fileMenu});return module;}
bool printAssignment(QPrinter& printer,const AssignmentController& c,const QFont& font){if(!c.data() || !c.result())return false;try{QString html="<h1>Assignment Problems</h1>";const auto line=[&](const QString& text){html+="<p>"+text.toHtmlEscaped()+"</p>";};line(c.data()->title);for(const auto& row:assignmentLines(c))line(row);html+="<h2>Original matrix</h2>";for(std::size_t i=0;i<c.data()->model.costs.rows();++i){QStringList cells;for(std::size_t j=0;j<c.data()->model.costs.columns();++j)cells<<c.data()->jobs[static_cast<int>(j)]+" = "+number(c,c.data()->model.costs(i,j));line(c.data()->workers[static_cast<int>(i)]+": "+cells.join("; "));}html+="<h2>Square padded minimization certificate</h2>";for(bool row:{true,false}){const auto& values=row?c.result()->rowPotential:c.result()->columnPotential;for(std::size_t i=0;i<values.size();++i)line(QStringLiteral("%1 %2: %3").arg(row?"Row":"Column").arg(i+1).arg(number(c,values[i])));}html+="<h2>Complete recorded history</h2>";for(std::size_t i=0;i<c.result()->history.size();++i)html+="<pre>"+assignmentStepText(*c.data(),*c.result(),static_cast<int>(i)).toHtmlEscaped()+"</pre>";QTextDocument document;document.setDefaultFont(usableUiFont(font));auto option=document.defaultTextOption();option.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);document.setDefaultTextOption(option);document.setHtml(html);document.print(&printer);return printer.printerState()!=QPrinter::Error && printer.printerState()!=QPrinter::Aborted;}catch(const std::exception&){return false;}}
